const $ = (q,root=document)=>root.querySelector(q);
const app=$('#app');
const state={user:null,activeExam:null,currentClass:null,liveCleanup:null,system:{initialized:true,schema_ready:true},site:{}};

const icons={
  home:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m3 11 9-8 9 8"/><path d="M5 10v10h14V10"/></svg>',
  class:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 5h16v14H4z"/><path d="M8 9h8M8 13h5"/></svg>',
  live:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="14" height="14" rx="2"/><path d="m17 10 4-3v10l-4-3"/></svg>',
  support:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M8 15v-4a4 4 0 0 1 8 0v4M8 14H6v3h3M16 14h2v3h-3"/></svg>',
  admin:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3 4 7v5c0 5 3.4 8.7 8 9 4.6-.3 8-4 8-9V7z"/><path d="m9 12 2 2 4-4"/></svg>',
  book:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H11v16H6.5A2.5 2.5 0 0 0 4 21.5z"/><path d="M20 5.5A2.5 2.5 0 0 0 17.5 3H13v16h4.5a2.5 2.5 0 0 1 2.5 2.5z"/></svg>',
  shield:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 3 5 6v6c0 4.6 2.8 7.8 7 9 4.2-1.2 7-4.4 7-9V6z"/><path d="m9 12 2 2 4-4"/></svg>',
  spark:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m12 3 1.7 4.3L18 9l-4.3 1.7L12 15l-1.7-4.3L6 9l4.3-1.7z"/><path d="m19 15 .9 2.1L22 18l-2.1.9L19 21l-.9-2.1L16 18l2.1-.9z"/></svg>'
};

async function api(path,opt={}){const r=await fetch(path,{credentials:'include',...opt,headers:{...(opt.body instanceof FormData?{}:{'content-type':'application/json'}),...(opt.headers||{})}});let j={};try{j=await r.json()}catch{}if(!r.ok||j.ok===false){const e=new Error(j.message||`HTTP ${r.status}`);e.data=j;e.status=r.status;throw e}return j}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function safeRichHtml(html=''){const doc=new DOMParser().parseFromString(String(html),'text/html');doc.querySelectorAll('script,style,iframe,object,embed,link,meta').forEach(x=>x.remove());doc.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{const n=a.name.toLowerCase(),v=a.value.trim().toLowerCase();if(n.startsWith('on')||n==='srcdoc'||((n==='href'||n==='src')&&v.startsWith('javascript:')))el.removeAttribute(a.name)})});return doc.body.innerHTML}
function downloadJson(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function footer(){const s=state.site||{};return `<footer class="footer"><div class="footer-inner"><div><b>${esc(s.site_name||'Trung tâm Học tập Số Sky First Network')}</b><div class="footer-en">${esc(s.site_name_en||'Sky First Network Digital Learning Center')}</div><div class="footer-note">${esc(s.footer_product_text||'Một sản phẩm thuộc hệ sinh thái Sky First Network.')}</div></div><div class="footer-right"><div><a href="#privacy">Chính sách quyền riêng tư</a><a href="#security">Bảo mật</a><a href="#terms">Điều khoản sử dụng</a><a href="#support">Trung tâm hỗ trợ</a></div><div class="footer-note">Hỗ trợ: <b>${esc(s.support_email||'support@skyfirst.io.vn')}</b></div><div class="footer-note">${esc(s.footer_copyright||'© 2026 Sky First Network. Mọi quyền được bảo lưu.')}</div></div></div></footer>`}
function shell(content){return `<div class="shell"><header class="topbar"><div class="topbar-inner"><div class="brand" data-go="home"><img src="/assets/sky-first-logo.png" alt="Sky First Network"><div><b>TRUNG TÂM HỌC TẬP SỐ</b><small>Sky First Network Digital Learning Center</small></div></div><nav class="nav">${state.user?`<button data-go="home">${icons.home}Trang chủ</button><button data-go="classes">${icons.class}Lớp học</button><button data-go="support">${icons.support}Hỗ trợ</button><button data-go="account">Tài khoản</button>${['super_admin','school_admin','account_admin'].includes(state.user.role)?`<button data-go="admin">${icons.admin}Quản trị</button>`:''}<button data-logout>Đăng xuất</button>`:`<button data-go="home">Giới thiệu</button><button data-go="lookup">Tra cứu yêu cầu</button><button data-go="login">Đăng nhập</button><button class="btn primary" data-go="request">Yêu cầu cấp tài khoản</button>`}</nav></div></header><main class="main">${content}</main>${footer()}</div>`}
function bindNav(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.liveCleanup?.();state.liveCleanup=null;location.hash=b.dataset.go});$('[data-logout]')?.addEventListener('click',async()=>{state.liveCleanup?.();state.liveCleanup=null;await api('/api/auth/logout',{method:'POST',body:'{}'});state.user=null;location.hash='login';render()})}

function landing(){app.innerHTML=shell(`
<section class="hero public-hero"><div class="hero-copy"><div class="eyebrow">SKY FIRST NETWORK DIGITAL LEARNING CENTER</div><h1>${esc(state.site.public_intro_title||'Một không gian học tập số được xây dựng để đồng hành lâu dài.')}</h1><p>${esc(state.site.public_intro_text||'Trung tâm Học tập Số Sky First Network được phát triển như một không gian chung cho lớp học, học liệu, hoạt động trực tuyến, bài tập, kiểm tra và hỗ trợ trong một hành trình liền mạch.')}</p><div class="toolbar hero-actions"><button class="btn primary" data-go="request">Yêu cầu cấp tài khoản SFN</button><button class="btn" data-go="login">Đăng nhập tài khoản</button><button class="btn ghost" data-go="lookup">Tra cứu yêu cầu</button></div></div><div class="hero-brand-panel"><img src="/assets/sky-first-logo.png" alt="Sky First Network"><div class="eyebrow">TRUNG TÂM HỌC TẬP SỐ</div><h2>Học tập không chỉ diễn ra trong một buổi học.</h2><p>Mỗi lớp được thiết kế như một không gian xuyên suốt, nơi hoạt động trước, trong và sau buổi học được kết nối với nhau.</p></div></section>

<section class="public-section"><div class="section-heading"><div class="eyebrow">GIỚI THIỆU</div><h2>${esc(state.site.public_about_title||'Một trung tâm học tập số dành cho cách học và cách tổ chức hiện đại.')}</h2><p>${esc(state.site.public_about_text||'Trung tâm được phát triển để kết nối lớp học, học liệu, hoạt động trực tuyến, bài tập, kiểm tra và hỗ trợ trong cùng một hành trình, giúp người học không phải chuyển qua quá nhiều công cụ rời rạc.')}</p></div><div class="story-grid"><article class="story-card"><h3>Không chỉ là phòng họp trực tuyến</h3><p>Một buổi học trực tuyến chỉ là một phần của trải nghiệm. Trung tâm Học tập Số Sky First Network đặt lớp học làm trung tâm, để người học có thể trở lại cùng một không gian sau mỗi buổi: xem thông báo, tiếp tục bài học, mở tài liệu, hoàn thành bài tập, tham gia kiểm tra, xem lịch và trao đổi với người phụ trách. Cách tổ chức này giúp lớp học không bị “mất dấu” sau khi cuộc gọi kết thúc.</p><p>Phòng học trực tuyến được kết nối trực tiếp với lớp, vì vậy giáo viên không phải tạo một hệ thống hoàn toàn khác cho từng buổi. Học viên có thể đi từ trang lớp vào buổi học, rồi trở lại đúng lớp khi kết thúc. Những công cụ như camera, micro, trình chiếu màn hình, chat và quyền điều phối được đặt trong bối cảnh học tập thay vì chỉ phục vụ hội họp.</p></article><article class="story-card"><h3>Một tài khoản, một hành trình thống nhất</h3><p>Tài khoản SFN không được tạo tự do ngay trên website. Người dùng gửi yêu cầu, cung cấp thông tin cần thiết và được xét trước khi tài khoản được cấp. Cách tiếp cận này giúp hệ thống kiểm soát tốt hơn phạm vi sử dụng, vai trò và quyền truy cập, đồng thời chuẩn bị cho khả năng tài khoản được dùng chung trong những dịch vụ khác thuộc hệ sinh thái Sky First Network.</p><p>Thông tin xác minh, ảnh học sinh/sinh viên và dữ liệu riêng tư không được xem như nội dung công khai. Các chức năng tài khoản, lớp học và quản trị được phân quyền theo vai trò, để một học viên, giáo viên, trợ giảng hay quản trị viên chỉ tiếp cận những khu vực phù hợp với nhiệm vụ của mình.</p></article></div></section>

${(state.siteAnnouncements||[]).length?`<section class="public-section"><div class="section-heading"><div class="eyebrow">THÔNG BÁO</div><h2>Thông tin mới từ Trung tâm</h2></div><div class="grid">${state.siteAnnouncements.map(a=>`<article class="card"><h3>${esc(a.title)}</h3><p class="muted">${esc(a.body)}</p></article>`).join('')}</div></section>`:''}

<section class="public-section"><div class="section-heading"><div class="eyebrow">KHÔNG GIAN HỌC TẬP</div><h2>Từ học liệu đến lớp trực tuyến, mọi phần đều hướng về cùng một lớp học.</h2><p>Không gian được tổ chức theo các nhóm chức năng rõ ràng để người dùng không phải học cách sử dụng một “bảng điều khiển kỹ thuật”.</p></div><div class="feature-grid"><div class="feature-card">${icons.class}<h3>Lớp học xuyên suốt</h3><p>Bảng tin, thành viên, mã lớp, QR, học liệu, bài tập, kiểm tra và các buổi học trực tuyến nằm trong cùng một không gian lớp.</p></div><div class="feature-card">${icons.live}<h3>Phòng học trực tuyến</h3><p>Camera, micro, trình chiếu màn hình và trò chuyện realtime được thiết kế cho nhu cầu học tập, với giáo viên và người điều phối giữ quyền quản lý phù hợp.</p></div><div class="feature-card">${icons.book}<h3>Kho học liệu trực tiếp</h3><p>Tài liệu được tải thẳng lên hệ thống thay vì buộc người dùng nhập URL. File lớn được lưu trong kho đối tượng và chỉ mở theo quyền truy cập.</p></div><div class="feature-card">${icons.spark}<h3>Tài liệu thành hoạt động học</h3><p>PDF, TXT, CSV và các nguồn nội dung phù hợp có thể được trích xuất để tạo bản nháp câu hỏi, hỗ trợ giáo viên xây quiz và ngân hàng câu hỏi nhanh hơn.</p></div><div class="feature-card">${icons.shield}<h3>Kiểm tra có chế độ tập trung</h3><p>Khi bắt đầu phiên kiểm tra nghiêm ngặt, các khu vực hỗ trợ khác trong Trung tâm có thể bị khóa cho đến khi học viên nộp bài hoặc phiên thi kết thúc.</p></div><div class="feature-card">${icons.support}<h3>Hỗ trợ có theo dõi</h3><p>Người dùng có thể gửi yêu cầu hỗ trợ và nhận mã ticket để theo dõi, thay vì phải tự tìm đúng người phụ trách qua nhiều kênh khác nhau.</p></div></div></section>

<section class="public-section public-split"><div><div class="eyebrow">HỌC LIỆU & ĐÁNH GIÁ</div><h2>Biến tài liệu thành nội dung có thể học, luyện tập và đánh giá.</h2><p>Giáo viên có thể đưa tài liệu trực tiếp vào lớp, tổ chức thành bài học, giao bài hoặc dùng nội dung tài liệu để tạo câu hỏi nháp. Bản nháp không tự động trở thành đề chính thức: người phụ trách vẫn là người kiểm tra, điều chỉnh và quyết định nội dung trước khi sử dụng với học viên.</p><p>Hệ thống bài tập hỗ trợ cả hoạt động học tập và nhiệm vụ dành cho tình nguyện viên. Mỗi nhiệm vụ có thể gắn hướng dẫn, thời hạn, nội dung nộp và file đính kèm. Với kiểm tra định kỳ, bài làm được lưu trong phiên, sự kiện kỹ thuật có thể được ghi nhận để hỗ trợ giáo viên xem lại bối cảnh làm bài, nhưng không tự động kết luận một học viên gian lận chỉ dựa trên một tín hiệu đơn lẻ.</p></div><div class="quote-panel"><span>“</span><p>Mục tiêu không phải đưa thật nhiều nút lên màn hình. Mục tiêu là để mỗi chức năng xuất hiện đúng lúc người học cần nó và vẫn liên kết được với toàn bộ hành trình của lớp.</p></div></section>

<section class="public-section"><div class="section-heading"><div class="eyebrow">TÀI KHOẢN & QUYỀN RIÊNG TƯ</div><h2>Quyền truy cập được cấp theo nhu cầu, không phải ai cũng nhìn thấy mọi thứ.</h2></div><div class="story-grid"><article class="story-card"><h3>Yêu cầu cấp tài khoản có xác minh</h3><p>Người chưa có tài khoản có thể gửi yêu cầu cấp tài khoản SFN bằng thông tin cá nhân, đơn vị học tập, vai trò và mục đích sử dụng. Sau khi gửi, hệ thống tạo một mã tra cứu riêng và gửi mã này đến email đã đăng ký từ <b>slc@skyfirst.io.vn</b>. Người gửi dùng mã cùng email để kiểm tra trạng thái xử lý mà không cần có tài khoản trước.</p><p>Khi yêu cầu được duyệt, người dùng nhận SFN ID và liên kết kích hoạt để tự thiết lập mật khẩu. Tài khoản đầu tiên của hệ thống được khởi tạo qua quy trình quản trị riêng và chức năng khởi tạo sẽ không còn được mở sau khi hệ thống đã có người quản trị.</p></article><article class="story-card"><h3>Bảo vệ dữ liệu theo mục đích sử dụng</h3><p>Ảnh chân dung, ảnh thẻ học sinh/sinh viên, bài nộp và những tệp riêng tư không được mặc định công khai. Hệ thống tách dữ liệu tệp khỏi dữ liệu quan hệ để phù hợp với cách lưu trữ và kiểm soát quyền truy cập. Các phiên đăng nhập có thời hạn, mật khẩu được băm trước khi lưu và những khu vực quản trị chỉ mở cho vai trò có quyền.</p><p>Nếu cần hỗ trợ về tài khoản, lớp học hoặc kỹ thuật, người dùng có thể liên hệ <b>support@skyfirst.io.vn</b> hoặc sử dụng Trung tâm hỗ trợ sau khi đăng nhập.</p></article></div></section>

<section class="closing-cta"><div><div class="eyebrow">BẮT ĐẦU</div><h2>Đã có tài khoản? Tiếp tục hành trình học tập của bạn.</h2><p>Nếu chưa có tài khoản SFN, hãy gửi yêu cầu và lưu mã tra cứu được hệ thống cung cấp.</p></div><div class="toolbar"><button class="btn primary" data-go="login">Đăng nhập</button><button class="btn" data-go="request">Yêu cầu cấp tài khoản</button></div></section>
`);bindNav()}

function login(){app.innerHTML=shell(`<div class="auth-wrap"><form class="auth-card" id="loginForm"><div class="eyebrow">TÀI KHOẢN SKY FIRST</div><h1>Chào mừng bạn quay trở lại</h1><p class="muted">Đăng nhập để tiếp tục lớp học, lịch học và những hoạt động được phân quyền cho tài khoản của bạn.</p><div class="field"><label>SFN ID hoặc email</label><input name="login" required autocomplete="username" placeholder="SFN00001 hoặc email"></div><div class="field"><label>Mật khẩu</label><input name="password" required type="password" autocomplete="current-password"></div><div id="msg"></div><button class="btn primary" style="width:100%">Đăng nhập</button><div class="notice">Nếu bạn chưa được cấp tài khoản SFN, vui lòng <a href="#request"><b>gửi yêu cầu cấp tài khoản</b></a>.</div></form></div>`);bindNav();$('#loginForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(d)});await loadMe();location.hash='home';render()}catch(x){$('#msg').innerHTML=`<div class="notice bad">${esc(x.message)}</div>`}}}

function requestAccount(){app.innerHTML=shell(`<section class="form-intro"><div class="eyebrow">YÊU CẦU CẤP TÀI KHOẢN SFN</div><h1>Bắt đầu hành trình với Sky First</h1><p>Cung cấp thông tin cần thiết để bộ phận phụ trách xác minh hồ sơ và xem xét phạm vi quyền truy cập phù hợp. Ảnh xác minh chỉ phục vụ quá trình xét duyệt và không được hiển thị công khai.</p></section><div class="auth-wrap request-wrap"><form class="auth-card auth-card-wide" id="reqForm"><div class="progress"><i style="width:100%"></i></div><h3>Thông tin cá nhân</h3><div class="two"><div class="field"><label>Họ và tên *</label><input name="full_name" required></div><div class="field"><label>Ngày sinh</label><input name="birth_date" type="date"></div></div><div class="two"><div class="field"><label>Email cá nhân *</label><input name="email" type="email" required></div><div class="field"><label>Số điện thoại *</label><input name="phone" required></div></div><div class="two"><div class="field"><label>Giới tính</label><select name="gender"><option value="">Không chọn</option><option>Nam</option><option>Nữ</option><option>Khác</option></select></div><div class="field"><label>Tỉnh/Thành</label><input name="province"></div></div><div class="two"><div class="field"><label>Ảnh chân dung/học sinh *</label><input name="portrait" type="file" accept="image/jpeg,image/png,image/webp" required><small class="field-help">JPG, PNG hoặc WEBP. Ảnh rõ mặt và đủ sáng.</small></div><div class="field"><label>Ảnh thẻ HS/SV hoặc giấy tờ học tập</label><input name="student_card" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"><small class="field-help">Không bắt buộc nếu bạn chưa có giấy tờ phù hợp.</small></div></div><h3>Thông tin học tập</h3><div class="two"><div class="field"><label>Loại đơn vị học tập</label><select name="education_unit_type"><option>THCS</option><option>THPT</option><option>GDTX</option><option>Trung cấp</option><option>Cao đẳng</option><option>Đại học</option><option>Khác</option></select></div><div class="field"><label>Trường / đơn vị học tập</label><input name="education_unit"></div></div><div class="three"><div class="field"><label>Lớp / Khóa</label><input name="class_name"></div><div class="field"><label>Mã HS/SV</label><input name="student_code"></div><div class="field"><label>Năm học</label><input name="academic_year" placeholder="2026–2027"></div></div><div class="two"><div class="field"><label>Khoa</label><input name="faculty"></div><div class="field"><label>Ngành</label><input name="major"></div></div><h3>Thông tin SFN & nhu cầu sử dụng</h3><div class="two"><div class="field"><label>Đơn vị / chương trình thuộc SFN (nếu có)</label><input name="sfn_unit" placeholder="Ví dụ: SFEC, hoạt động TNV..."></div><div class="field"><label>Vai trò hiện tại</label><input name="sfn_role" placeholder="Học viên, TNV, giáo viên..."></div></div><div class="field"><label>Nhu cầu quyền truy cập</label><select name="requested_access"><option value="student">Học viên / Thành viên</option><option value="teacher">Giáo viên / Người quản lý lớp</option></select></div><div class="field"><label>Mục đích sử dụng</label><textarea name="purpose" placeholder="Bạn cần tài khoản để tham gia lớp, quản lý lớp, hoạt động học tập hoặc công việc nào?"></textarea></div><div class="two"><div class="field"><label>Mã / người giới thiệu</label><input name="referral"></div><div class="field"><label>Ghi chú bổ sung</label><input name="notes"></div></div><label class="notice consent"><input type="checkbox" required> Tôi xác nhận thông tin cung cấp là chính xác và đồng ý với Điều khoản sử dụng, Chính sách quyền riêng tư và Chính sách bảo mật.</label><div id="msg"></div><button class="btn primary" style="width:100%">Gửi yêu cầu cấp tài khoản</button><p class="field-help center">Sau khi gửi, hệ thống tạo mã tra cứu và gửi xác nhận từ <b>slc@skyfirst.io.vn</b> đến email đăng ký.</p></form></div>`);bindNav();$('#reqForm').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;btn.textContent='Đang gửi yêu cầu...';try{const j=await api('/api/auth/request-account',{method:'POST',body:new FormData(e.target)});$('#msg').innerHTML=`<div class="request-success"><div class="eyebrow">YÊU CẦU ĐÃ ĐƯỢC TIẾP NHẬN</div><h3>Vui lòng lưu mã tra cứu</h3><div class="request-code">${esc(j.request_code)}</div><p>Mã này được dùng cùng email đăng ký để theo dõi trạng thái. ${j.email_sent?'Email xác nhận đã được gửi.':'Hệ thống đã tạo mã; nếu email chưa đến, bạn vẫn có thể lưu mã này để tra cứu.'}</p><button type="button" class="btn" data-go="lookup">Tra cứu yêu cầu</button></div>`;e.target.reset();bindNav();$('#msg').scrollIntoView({behavior:'smooth',block:'center'})}catch(x){$('#msg').innerHTML=`<div class="notice bad">${esc(x.message)}</div>`}finally{btn.disabled=false;btn.textContent='Gửi yêu cầu cấp tài khoản'}}}

function lookupAccount(){app.innerHTML=shell(`<section class="form-intro"><div class="eyebrow">TRA CỨU YÊU CẦU</div><h1>Theo dõi trạng thái cấp tài khoản</h1><p>Sử dụng mã yêu cầu được cấp sau khi gửi hồ sơ và email đã đăng ký. Hệ thống chỉ hiển thị thông tin của yêu cầu khớp với cả hai dữ liệu này.</p></section><div class="grid lookup-grid"><div class="card wide"><form id="lookupForm"><div class="two"><div class="field"><label>Mã yêu cầu</label><input name="request_code" required placeholder="SLC-ACC-..."></div><div class="field"><label>Email đã đăng ký</label><input name="email" type="email" required placeholder="name@example.com"></div></div><button class="btn primary">Tra cứu</button></form></div><div class="card" id="lookupResult"><h3>Kết quả tra cứu</h3><p class="muted">Nhập đầy đủ thông tin và chọn Tra cứu. Trạng thái hồ sơ sẽ được lấy trực tiếp từ hệ thống.</p></div></div>`);bindNav();$('#lookupForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const root=$('#lookupResult');root.innerHTML='<h3>Đang tra cứu...</h3>';try{const j=await api('/api/auth/lookup-account-request',{method:'POST',body:JSON.stringify(d)});const r=j.request;root.innerHTML=`<div class="eyebrow">${esc(r.request_code)}</div><h3>${esc(r.status_label)}</h3><p class="muted">Yêu cầu được ghi nhận lúc ${esc(r.created_at)}.</p><div class="notice">Các cập nhật quan trọng về yêu cầu sẽ được gửi đến email bạn đã đăng ký.</div>`}catch(x){root.innerHTML=`<h3>Không tìm thấy kết quả</h3><div class="notice bad">${esc(x.message)}</div>`}}}

function setupFirstAdmin(){
  const ready=state.system.schema_ready;
  app.innerHTML=`<div class="setup-page"><div class="setup-shell"><div class="setup-brand"><img src="/assets/sky-first-logo.png"><div><div class="eyebrow">THIẾT LẬP HỆ THỐNG</div><h1>${ready?'Khởi tạo quản trị đầu tiên':'Cài đặt dữ liệu nền tảng'}</h1><p>${ready?'Tạo tài khoản quản trị đầu tiên để bắt đầu vận hành Trung tâm. Sau bước này, hầu hết thao tác quản trị được thực hiện trực tiếp trên website.':'Cơ sở dữ liệu chưa được cài đặt. Bạn có thể tạo toàn bộ bảng và cấu trúc cần thiết ngay tại đây, không cần mở terminal hay chạy SQL thủ công.'}</p></div></div>${!ready?`<form class="auth-card auth-card-wide" id="installForm"><div class="notice"><b>Cài đặt một chạm</b><br>Hệ thống sẽ tự tạo cấu trúc dữ liệu, thiết lập mặc định và chuẩn bị Control Center.</div><div class="field"><label>Mã thiết lập hệ thống</label><input name="setup_token" type="password" required></div><div id="msg"></div><button class="btn primary" style="width:100%">Cài đặt dữ liệu hệ thống</button></form>`:`<form class="auth-card auth-card-wide" id="setupForm"><div class="two"><div class="field"><label>Họ và tên quản trị viên</label><input name="full_name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div></div><div class="field"><label>Số điện thoại</label><input name="phone"></div><div class="two"><div class="field"><label>Mật khẩu</label><input name="password" type="password" minlength="12" required></div><div class="field"><label>Xác nhận mật khẩu</label><input name="confirm_password" type="password" minlength="12" required></div></div><div class="field"><label>Mã thiết lập hệ thống</label><input name="setup_token" type="password" required></div><div id="msg"></div><button class="btn primary" style="width:100%">Khởi tạo quản trị đầu tiên</button></form>`}</div></div>`;
  if(!ready){$('#installForm').onsubmit=async e=>{e.preventDefault();const token=new FormData(e.target).get('setup_token');try{await api('/api/setup/install',{method:'POST',headers:{'x-setup-token':token},body:'{}'});state.system.schema_ready=true;$('#msg').innerHTML='<div class="notice good"><b>Cài đặt thành công.</b> Đang chuyển sang bước tạo quản trị viên...</div>';setTimeout(()=>setupFirstAdmin(),700)}catch(x){const d=x.data?.detail||{};const technical=d.stage?`<div style="margin-top:10px;font-size:13px;line-height:1.65"><b>Bước lỗi:</b> ${esc(d.stage)}${d.statement_index?`<br><b>Câu lệnh:</b> ${esc(d.statement_index)} / ${esc(d.statement_total||'?')}`:''}${d.statement_preview?`<br><b>SQL:</b> <code style="white-space:pre-wrap;word-break:break-word">${esc(d.statement_preview)}</code>`:''}${d.error?`<br><b>D1:</b> ${esc(d.error)}`:''}${d.cause?`<br><b>Chi tiết:</b> ${esc(d.cause)}`:''}${d.installer?`<br><b>Installer:</b> ${esc(d.installer)}`:''}<br><b>Có thể chạy lại:</b> ${d.retry_safe?'Có':'Không xác định'}</div>`:'';$('#msg').innerHTML=`<div class="notice bad"><b>${esc(x.message)}</b>${technical}</div>`}};return;}
  $('#setupForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.password!==d.confirm_password){$('#msg').innerHTML='<div class="notice bad">Mật khẩu xác nhận không khớp.</div>';return}try{const j=await api('/api/setup/bootstrap',{method:'POST',headers:{'x-setup-token':d.setup_token},body:JSON.stringify({full_name:d.full_name,email:d.email,phone:d.phone,password:d.password})});$('#msg').innerHTML=`<div class="notice good"><b>Khởi tạo thành công.</b><br>SFN ID quản trị: ${esc(j.sfn_id)}. Từ đây bạn có thể quản lý hệ thống trên website.</div>`;state.system.initialized=true;setTimeout(()=>{location.hash='login'},1000)}catch(x){$('#msg').innerHTML=`<div class="notice bad">${esc(x.message)}</div>`}}
}

async function home(){const [cls]=await Promise.all([api('/api/classes')]);app.innerHTML=shell(`<section class="hero"><div class="eyebrow">Xin chào, ${esc(state.user.full_name)}</div><h1>Không gian học tập của bạn.</h1><p>${esc(state.user.sfn_id)} · ${esc(state.user.role)} · Tài khoản SFN dùng chung cho hệ sinh thái.</p></section><section class="grid"><div class="card"><div class="muted">Lớp đang tham gia</div><div class="metric">${cls.classes.length}</div></div><div class="card"><div class="muted">Tài khoản</div><div class="metric" style="font-size:24px">${esc(state.user.sfn_id)}</div></div><div class="card"><div class="muted">Hỗ trợ</div><div style="margin-top:10px"><b>support@skyfirst.io.vn</b></div></div><div class="card full"><h3>Lớp gần đây</h3><div class="list">${cls.classes.slice(0,6).map(c=>`<div class="item"><b>${esc(c.name)}</b> <span class="pill">${esc(c.member_role)}</span><div class="muted">${esc(c.unit||'Sky First Network')} · ${c.member_count||0} thành viên</div><button class="btn" data-class="${c.id}" style="margin-top:10px">Mở lớp</button></div>`).join('')||'<div class="muted">Bạn chưa tham gia lớp nào.</div>'}</div></div></section>`);bindNav();document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{location.hash=`class/${b.dataset.class}`})}

async function classes(){const j=await api('/api/classes');app.innerHTML=shell(`<section class="hero"><div class="eyebrow">Lớp học</div><h1>Lớp của tôi</h1><p>Tham gia bằng mã lớp hoặc quản lý lớp được cấp quyền.</p><div class="toolbar"><input id="joinCode" placeholder="Mã lớp" style="padding:12px;border-radius:14px;border:1px solid var(--line);background:rgba(255,255,255,.08);color:white"><button class="btn primary" id="joinBtn">Tham gia</button>${['super_admin','school_admin','teacher'].includes(state.user.role)?'<button class="btn" id="createBtn">Tạo lớp</button>':''}</div><div id="msg"></div></section><section class="grid">${j.classes.map(c=>`<div class="card"><h3>${esc(c.name)}</h3><p class="muted">${esc(c.description||'Không có mô tả')}</p><div class="pill">${esc(c.join_code)}</div><div style="margin-top:12px"><button class="btn" data-class="${c.id}">Mở lớp</button></div></div>`).join('')||'<div class="card full">Chưa có lớp.</div>'}</section>`);bindNav();$('#joinBtn').onclick=async()=>{try{const r=await api('/api/classes/join',{method:'POST',body:JSON.stringify({code:$('#joinCode').value})});location.hash=`class/${r.class_id}`}catch(e){$('#msg').innerHTML=`<div class="notice bad">${esc(e.message)}</div>`}};$('#createBtn')?.addEventListener('click',async()=>{const name=prompt('Tên lớp');if(!name)return;const r=await api('/api/classes',{method:'POST',body:JSON.stringify({name,description:'',unit:'Sky First Network'})});location.hash=`class/${r.id}`});document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>location.hash=`class/${b.dataset.class}`)}

async function classView(id){const [d,p,m,a,e]=await Promise.all([api(`/api/classes/${id}`),api(`/api/classes/${id}/posts`),api(`/api/classes/${id}/materials`),api(`/api/classes/${id}/assignments`),api(`/api/classes/${id}/exams`)]);state.currentClass=d.class;app.innerHTML=shell(`<section class="hero"><div class="eyebrow">${esc(d.class.unit||'SLC')}</div><h1>${esc(d.class.name)}</h1><p>${esc(d.class.description||'Không gian lớp học số')}</p><div class="toolbar"><span class="pill">Mã lớp: ${esc(d.class.join_code)}</span><button class="btn primary" id="liveBtn">${icons.live}Mở phòng học</button><button class="btn" id="qrBtn">QR lớp</button>${['teacher','assistant'].includes(d.my_role)?'<button class="btn" id="guestLinkBtn">Sao chép link khách</button>':''}</div><div id="qrArea" style="margin-top:15px"></div></section><div class="tabs"><button class="tab active" data-tab="feed">Bảng tin</button><button class="tab" data-tab="materials">Học liệu</button><button class="tab" data-tab="assignments">Bài tập & TNV</button><button class="tab" data-tab="exams">Kiểm tra</button><button class="tab" data-tab="chat">Trao đổi</button><button class="tab" data-tab="schedule">Lịch lớp</button><button class="tab" data-tab="members">Thành viên</button></div><section id="tabContent"></section>`);bindNav();const data={feed:p.posts,materials:m.materials,assignments:a.assignments,exams:e.exams,members:d.members};const renderTab=async t=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===t));const root=$('#tabContent');if(t==='feed')root.innerHTML=`<div class="grid"><div class="card full"><h3>Đăng lên lớp</h3><textarea id="postBody" placeholder="Thông báo, nội dung học..."></textarea><button class="btn primary" id="postBtn">Đăng</button></div>${data.feed.map(x=>`<div class="card full"><b>${esc(x.author)}</b> ${x.pinned?'<span class="pill">Đã ghim</span>':''}<p>${esc(x.body)}</p><div class="muted">${esc(x.created_at)}</div></div>`).join('')}</div>`;if(t==='materials')root.innerHTML=`<div class="grid"><div class="card full"><h3>Tải tài liệu lên</h3><form id="matForm"><div class="two"><div class="field"><input name="title" placeholder="Tên tài liệu"></div><div class="field"><input name="file" type="file" required></div></div><button class="btn primary">Tải lên</button></form><div class="notice">PDF/TXT/CSV có thể dùng để tạo quiz nháp ngay trên web. PDF sẽ được trích văn bản tại trình duyệt.</div></div>${data.materials.map(x=>`<div class="card"><b>${esc(x.title)}</b><div class="muted">${esc(x.name)} · ${(x.size/1024).toFixed(1)} KB</div><button class="btn" data-quiz-file="${x.id}" data-name="${esc(x.name)}" style="margin-top:10px">Tạo quiz từ tài liệu</button></div>`).join('')}</div>`;if(t==='assignments')root.innerHTML=`<div class="grid"><div class="card full"><h3>Bài tập & nhiệm vụ</h3>${['teacher','assistant'].includes(d.my_role)?'<button class="btn primary" id="newAssignment">Tạo mới</button>':''}</div>${data.assignments.map(x=>`<div class="card"><span class="pill">${x.type==='tnv_task'?'Nhiệm vụ TNV':'Bài tập'}</span><h3>${esc(x.title)}</h3><p class="muted">${esc(x.instructions)}</p>${['teacher','assistant'].includes(d.my_role)?`<button class="btn" data-grade-assignment="${x.id}">Bài nộp & chấm điểm</button>`:`<button class="btn" data-submit-assignment="${x.id}">Nộp bài</button>`}</div>`).join('')}</div>`;if(t==='exams')root.innerHTML=`<div class="grid"><div class="card full"><h3>Kiểm tra định kỳ</h3>${['teacher','assistant'].includes(d.my_role)?'<button class="btn primary" id="newExam">Tạo bài kiểm tra</button>':''}</div>${data.exams.map(x=>`<div class="card"><h3>${esc(x.title)}</h3><p class="muted">${x.duration_minutes} phút · ${x.strict_mode?'Chế độ tập trung':'Bình thường'}</p><button class="btn warn" data-exam="${x.id}">Bắt đầu</button></div>`).join('')}</div>`;if(t==='chat'){root.innerHTML='<div class="card full"><h3>Trao đổi lớp học</h3><p class="muted">Đang tải cuộc trò chuyện...</p></div>';const j=await api(`/api/classes/${id}/chat`);root.innerHTML=`<div class="card full"><h3>Trao đổi lớp học</h3><div class="list" id="classChatList">${j.messages.map(x=>`<div class="item"><b>${esc(x.full_name)}</b> <span class="pill">${esc(x.role)}</span><div>${esc(x.body)}</div><div class="muted">${esc(x.created_at)}</div></div>`).join('')||'<div class="muted">Chưa có tin nhắn.</div>'}</div><div class="field" style="margin-top:14px"><textarea id="classChatText" placeholder="Trao đổi với lớp..."></textarea></div><button class="btn primary" id="classChatSend">Gửi tin nhắn</button></div>`;$('#classChatSend').onclick=async()=>{const body=$('#classChatText').value.trim();if(!body)return;await api(`/api/classes/${id}/chat`,{method:'POST',body:JSON.stringify({body})});renderTab('chat')}}
if(t==='schedule'){root.innerHTML='<div class="card full"><h3>Lịch lớp</h3><p class="muted">Đang tải lịch...</p></div>';const j=await api(`/api/classes/${id}/events`);root.innerHTML=`<div class="grid">${['teacher','assistant'].includes(d.my_role)?`<form class="card full" id="eventForm"><h3>Thêm lịch</h3><div class="two"><div class="field"><label>Tên hoạt động</label><input name="title" required></div><div class="field"><label>Loại</label><select name="event_type"><option value="class">Buổi học</option><option value="live">Học trực tuyến</option><option value="exam">Kiểm tra</option><option value="deadline">Hạn nộp</option><option value="other">Khác</option></select></div></div><div class="two"><div class="field"><label>Bắt đầu</label><input name="starts_at" type="datetime-local" required></div><div class="field"><label>Kết thúc</label><input name="ends_at" type="datetime-local"></div></div><div class="field"><textarea name="details" placeholder="Ghi chú"></textarea></div><button class="btn primary">Thêm vào lịch</button></form>`:''}${j.events.map(x=>`<div class="card"><span class="pill">${esc(x.event_type)}</span><h3>${esc(x.title)}</h3><p class="muted">${esc(x.starts_at)}${x.ends_at?' → '+esc(x.ends_at):''}</p><p>${esc(x.details||'')}</p></div>`).join('')||'<div class="card full muted">Chưa có lịch sắp tới.</div>'}</div>`;$('#eventForm')?.addEventListener('submit',async ev=>{ev.preventDefault();const z=Object.fromEntries(new FormData(ev.target));await api(`/api/classes/${id}/events`,{method:'POST',body:JSON.stringify(z)});renderTab('schedule')})}
if(t==='members')root.innerHTML=`<div class="card full"><h3>Thành viên</h3><div class="list">${data.members.map(x=>`<div class="item"><b>${esc(x.full_name)}</b> <span class="pill">${esc(x.role)}</span><div class="muted">${esc(x.sfn_id)}</div></div>`).join('')}</div></div>`;bindClassActions(t)};document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>renderTab(b.dataset.tab));$('#liveBtn').onclick=()=>location.hash=`live/${id}`;$('#qrBtn').onclick=()=>{const area=$('#qrArea');area.innerHTML='<div class="qrbox"><canvas id="qrCanvas"></canvas></div>';QRCode.toCanvas($('#qrCanvas'),`${location.origin}/#join/${encodeURIComponent(d.class.join_code)}`,{width:220})};$('#guestLinkBtn')?.addEventListener('click',async()=>{const link=`${location.origin}/#guest-live/${encodeURIComponent(id)}`;try{await navigator.clipboard.writeText(link);alert('Đã sao chép link tham gia phòng học dành cho khách.')}catch{prompt('Sao chép link khách:',link)}});renderTab('feed');
function bindClassActions(t){if(t==='feed')$('#postBtn')?.addEventListener('click',async()=>{await api(`/api/classes/${id}/posts`,{method:'POST',body:JSON.stringify({body:$('#postBody').value})});location.reload()});if(t==='materials'){$('#matForm')?.addEventListener('submit',async ev=>{ev.preventDefault();await api(`/api/classes/${id}/materials`,{method:'POST',body:new FormData(ev.target)});location.reload()});document.querySelectorAll('[data-quiz-file]').forEach(b=>b.onclick=()=>quizFromMaterial(b.dataset.quizFile,b.dataset.name,id))}if(t==='assignments'){$('#newAssignment')?.addEventListener('click',async()=>{const title=prompt('Tên bài tập/nhiệm vụ');if(!title)return;const type=confirm('OK = Nhiệm vụ TNV, Cancel = Bài tập')?'tnv_task':'assignment';await api(`/api/classes/${id}/assignments`,{method:'POST',body:JSON.stringify({title,type,instructions:'Hoàn thành theo yêu cầu của giáo viên/người phụ trách.',points:10})});location.reload()});document.querySelectorAll('[data-submit-assignment]').forEach(b=>b.onclick=async()=>{const text=prompt('Nội dung bài nộp');if(text===null)return;const fd=new FormData();fd.set('text',text);await api(`/api/assignments/${b.dataset.submitAssignment}/submit`,{method:'POST',body:fd});alert('Đã nộp bài.')});document.querySelectorAll('[data-grade-assignment]').forEach(b=>b.onclick=async()=>{const r=await api(`/api/assignments/${b.dataset.gradeAssignment}/submissions`);if(!r.submissions.length){alert('Chưa có bài nộp.');return}const pick=prompt('Nhập SFN ID cần chấm:\n'+r.submissions.map(x=>`${x.sfn_id} - ${x.full_name}${x.score!=null?' - '+x.score+'/'+r.assignment.points:''}`).join('\n'),r.submissions[0].sfn_id);if(!pick)return;const sub=r.submissions.find(x=>x.sfn_id.toLowerCase()===pick.toLowerCase());if(!sub){alert('Không tìm thấy bài nộp.');return}const score=prompt(`Điểm cho ${sub.full_name} (tối đa ${r.assignment.points})`,sub.score??'');if(score===null)return;const feedback=prompt('Nhận xét',sub.feedback||'')??'';await api(`/api/submissions/${sub.id}/grade`,{method:'PATCH',body:JSON.stringify({score,feedback})});alert('Đã lưu điểm và nhận xét.')})}if(t==='exams'){$('#newExam')?.addEventListener('click',()=>openExamBuilder(id));document.querySelectorAll('[data-exam]').forEach(b=>b.onclick=()=>startExam(b.dataset.exam))}}
}

async function quizFromMaterial(fileId,name,classId){let text='';if(/\.txt$|\.md$|\.csv$|\.json$/i.test(name)){const r=await fetch(`/api/files/${fileId}`);text=await r.text()}else if(/\.pdf$/i.test(name)){try{const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';const r=await fetch(`/api/files/${fileId}`);const buf=await r.arrayBuffer();const pdf=await pdfjs.getDocument({data:buf}).promise;for(let i=1;i<=Math.min(pdf.numPages,80);i++){const page=await pdf.getPage(i);const c=await page.getTextContent();text+=c.items.map(x=>x.str).join(' ')+'\n'}}catch(e){alert('Không thể trích nội dung PDF: '+e.message);return}}else{alert('Bản hiện tại tự trích nội dung PDF/TXT/MD/CSV/JSON. Tệp khác vẫn được lưu làm học liệu và có thể mở rộng bộ trích xuất.');return}try{const q=await api('/api/quiz/generate',{method:'POST',body:JSON.stringify({text,count:8})});const win=window.open('','_blank');win.document.write(`<pre style="white-space:pre-wrap;font-family:system-ui;padding:24px">${esc(JSON.stringify(q.questions,null,2))}</pre>`)}catch(e){alert(e.message)}}

function openExamBuilder(classId){
  const qs=[];
  app.innerHTML=shell(`<section class="hero"><div class="eyebrow">TẠO BÀI KIỂM TRA</div><h1>Soạn đề trực tiếp trên web</h1><p>Tạo câu hỏi mà không cần nhập JSON hay chỉnh mã nguồn. Bản V10 hỗ trợ trình soạn nhanh trắc nghiệm một lựa chọn và có thể mở rộng thêm dạng câu hỏi ở các phiên bản sau.</p></section><section class="grid"><form class="card full" id="examMeta"><div class="two"><div class="field"><label>Tên bài kiểm tra</label><input name="title" required></div><div class="field"><label>Thời lượng (phút)</label><input name="duration_minutes" type="number" min="1" max="720" value="30" required></div></div><label><input type="checkbox" name="strict_mode" checked> Bật chế độ tập trung</label></form><div class="card full"><h3>Thêm câu hỏi trắc nghiệm</h3><div class="field"><label>Câu hỏi</label><textarea id="qbText"></textarea></div><div class="two"><div class="field"><input id="qbA" placeholder="Đáp án A"></div><div class="field"><input id="qbB" placeholder="Đáp án B"></div></div><div class="two"><div class="field"><input id="qbC" placeholder="Đáp án C"></div><div class="field"><input id="qbD" placeholder="Đáp án D"></div></div><div class="two"><div class="field"><label>Đáp án đúng</label><select id="qbCorrect"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></div><div class="field"><label>Điểm</label><input id="qbPoints" type="number" min="0.25" step="0.25" value="1"></div></div><button class="btn" id="qbAdd">Thêm câu hỏi</button></div><div class="card full"><h3>Đề hiện tại</h3><div id="qbList" class="list"><div class="muted">Chưa có câu hỏi.</div></div><div class="toolbar" style="margin-top:14px"><button class="btn primary" id="qbPublish">Tạo & xuất bản bài kiểm tra</button><button class="btn" id="qbCancel">Hủy</button></div></div></section>`);
  bindNav();
  const draw=()=>{$('#qbList').innerHTML=qs.length?qs.map((q,i)=>`<div class="item"><b>Câu ${i+1}. ${esc(q.question)}</b><div class="muted">Đúng: ${esc(q.answer)} · ${q.points} điểm</div><button class="btn" data-qremove="${i}" style="margin-top:8px">Xóa</button></div>`).join(''):'<div class="muted">Chưa có câu hỏi.</div>';document.querySelectorAll('[data-qremove]').forEach(b=>b.onclick=()=>{qs.splice(Number(b.dataset.qremove),1);draw()})};
  $('#qbAdd').onclick=()=>{const text=$('#qbText').value.trim(),opts=[$('#qbA').value.trim(),$('#qbB').value.trim(),$('#qbC').value.trim(),$('#qbD').value.trim()];if(!text||opts.some(x=>!x)){alert('Vui lòng nhập câu hỏi và đủ 4 phương án.');return}const idx=Number($('#qbCorrect').value);qs.push({id:crypto.randomUUID(),type:'mcq',question:text,options:opts,answer:opts[idx],points:Math.max(.25,Number($('#qbPoints').value||1))});$('#qbText').value='';['#qbA','#qbB','#qbC','#qbD'].forEach(x=>$(x).value='');draw()};
  $('#qbPublish').onclick=async()=>{const meta=Object.fromEntries(new FormData($('#examMeta')));if(!meta.title?.trim()){alert('Vui lòng nhập tên bài kiểm tra.');return}if(!qs.length){alert('Vui lòng thêm ít nhất một câu hỏi.');return}await api(`/api/classes/${classId}/exams`,{method:'POST',body:JSON.stringify({title:meta.title,instructions:'',duration_minutes:Number(meta.duration_minutes||30),strict_mode:$('#examMeta').elements.strict_mode.checked,questions:qs})});alert('Đã tạo bài kiểm tra.');location.hash=`class/${classId}`;location.reload()};
  $('#qbCancel').onclick=()=>{location.hash=`class/${classId}`};
}

async function startExam(id){if(!confirm('Sau khi xác nhận, Trung tâm sẽ bật Chế độ kiểm tra và giới hạn các chức năng khác trong tài khoản cho tới khi nộp bài hoặc hết thời gian. Tiếp tục?'))return;const r=await api(`/api/exams/${id}/start`,{method:'POST',body:'{}'});location.hash=`exam/${r.attempt_id}`}
async function resumeExam(attemptId){try{const r=await api(`/api/exam-attempts/${attemptId}`);let local={};try{local=JSON.parse(localStorage.getItem(`sfn_exam_${attemptId}`)||'{}')}catch{};const answers={...(r.answers||{}),...(local.answers||{})};const events=[...(r.events||[]),...(local.events||[])].slice(-500);runExam(r.attempt_id,r.exam,answers,events,r.remaining_seconds)}catch(e){localStorage.removeItem(`sfn_exam_${attemptId}`);alert(e.message);await loadMe();location.hash='home'}}
function runExam(attemptId,exam,initialAnswers={},initialEvents=[],initialRemaining=null){const answers={...initialAnswers},events=[...initialEvents];let remaining=Number(initialRemaining??exam.duration_minutes*60);let submitted=false;document.documentElement.requestFullscreen?.().catch(()=>{});const log=type=>{events.push({type,at:new Date().toISOString()});if(events.length>500)events.splice(0,events.length-500)};const onVisibility=()=>{if(document.hidden)log('tab_hidden')},onBlur=()=>log('window_blur'),onFullscreen=()=>{if(!document.fullscreenElement)log('fullscreen_exit')},onCopy=()=>log('copy'),onPaste=()=>log('paste');document.addEventListener('visibilitychange',onVisibility);window.addEventListener('blur',onBlur);document.addEventListener('fullscreenchange',onFullscreen);document.addEventListener('copy',onCopy);document.addEventListener('paste',onPaste);let tickTimer=null,saveTimer=null;const cleanup=()=>{clearInterval(tickTimer);clearInterval(saveTimer);document.removeEventListener('visibilitychange',onVisibility);window.removeEventListener('blur',onBlur);document.removeEventListener('fullscreenchange',onFullscreen);document.removeEventListener('copy',onCopy);document.removeEventListener('paste',onPaste)};const draw=()=>{app.innerHTML=`<div class="exam-lock"><div class="main"><div class="hero"><div class="eyebrow">CHẾ ĐỘ KIỂM TRA</div><h1>${esc(exam.title)}</h1><p>Thời gian còn lại: <b id="time"></b>. Bài làm được tự động lưu định kỳ để giảm rủi ro khi mạng chập chờn hoặc trang được tải lại.</p></div><div class="grid">${exam.questions.map((q,i)=>`<div class="card full"><h3>Câu ${i+1}. ${esc(q.question)}</h3>${q.type==='mcq'?(q.options||[]).map(o=>`<label class="item" style="display:block"><input type="radio" name="q_${q.id}" value="${esc(o)}" ${String(answers[q.id]??'')===String(o)?'checked':''}> ${esc(o)}</label>`).join(''):`<textarea data-answer="${q.id}">${esc(answers[q.id]??'')}</textarea>`}</div>`).join('')}<div class="card full"><button class="btn warn" id="submitExam">Nộp bài & kết thúc phiên kiểm tra</button></div></div></div></div>`;const paintTime=()=>{const el=$('#time');if(el)el.textContent=`${Math.floor(Math.max(0,remaining)/60)}:${String(Math.max(0,remaining)%60).padStart(2,'0')}`};paintTime();tickTimer=setInterval(()=>{remaining--;paintTime();if(remaining<=0)submit(true)},1000);saveTimer=setInterval(save,12000);document.querySelectorAll('input[type=radio]').forEach(x=>x.onchange=()=>answers[x.name.slice(2)]=x.value);document.querySelectorAll('[data-answer]').forEach(x=>x.oninput=()=>answers[x.dataset.answer]=x.value);$('#submitExam').onclick=()=>submit(false)};async function save(){if(submitted)return;try{localStorage.setItem(`sfn_exam_${attemptId}`,JSON.stringify({answers,events,at:Date.now()}));await api(`/api/exam-attempts/${attemptId}/save`,{method:'POST',body:JSON.stringify({answers,events})})}catch{}}async function submit(auto=false){if(submitted)return;submitted=true;try{await save();const r=await api(`/api/exam-attempts/${attemptId}/submit`,{method:'POST',body:JSON.stringify({answers,events})});cleanup();localStorage.removeItem(`sfn_exam_${attemptId}`);document.exitFullscreen?.().catch(()=>{});alert(`${auto?'Đã hết thời gian. ':''}Bài đã được nộp. Điểm tự chấm: ${r.score}/${r.max_score}`);state.activeExam=null;await loadMe();location.hash='home';render()}catch(e){submitted=false;alert(e.message)}}draw()}

function guestLiveEntry(classId){app.innerHTML=shell(`<div class="auth-wrap"><form class="auth-card" id="guestLiveForm"><div class="eyebrow">THAM GIA PHÒNG HỌC</div><h1>Vào lớp với tư cách khách</h1><p class="muted">Bạn không cần tài khoản SFN để tham gia khi lớp cho phép khách. Micro và camera vẫn tắt mặc định.</p><div class="field"><label>Tên hiển thị</label><input name="name" minlength="2" maxlength="80" required placeholder="Họ và tên"></div><div id="msg"></div><button class="btn primary" style="width:100%">Tham gia phòng học</button></form></div>`);bindNav();$('#guestLiveForm').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();try{await liveRoom(classId,name)}catch(x){$('#msg').innerHTML=`<div class="notice bad">${esc(x.message)}</div>`}}}

async function liveRoom(classId,guestName=null){
  let d,access,displayName,leaveTarget;
  if(guestName){const info=await api(`/api/public/classes/${classId}/live-info`);access=await api(`/api/public/live/${classId}/guest-token`,{method:'POST',body:JSON.stringify({name:guestName})});d={class:info.class,my_role:'guest'};displayName=guestName;leaveTarget='home'}else{[d,access]=await Promise.all([api(`/api/classes/${classId}`),api('/api/live/access-token',{method:'POST',body:JSON.stringify({class_id:classId})})]);displayName=state.user.full_name;leaveTarget=`class/${classId}`;}const cls=d.class;
  app.innerHTML=shell(`<section class="hero live-hero"><div class="eyebrow">PHÒNG HỌC TRỰC TUYẾN</div><h1>${esc(cls.name)}</h1><p>Micro và camera của bạn được tắt mặc định. Hãy chỉ bật khi cần phát biểu, trình bày hoặc khi giáo viên yêu cầu.</p><div class="toolbar"><button class="btn primary" id="toggleMic">Bật micro</button><button class="btn" id="toggleCam">Bật camera</button><button class="btn" id="shareScreen">Trình chiếu</button><button class="btn warn" id="leaveRoom">Rời phòng</button></div><div id="mediaStatus" class="notice">Bạn đang tham gia với micro và camera tắt.</div></section><section class="room"><div class="stage" id="stage"><div class="video-tile local-tile"><video id="localVideo" autoplay playsinline muted></video><div class="video-placeholder" id="localPlaceholder"><img src="/assets/sky-first-logo.png" alt=""><b>${esc(displayName)}</b><span>Camera đang tắt</span></div><div class="video-label">${esc(displayName)} · Bạn</div></div></div><aside class="sidebar"><h3>Trò chuyện trong buổi học</h3><div id="chat" class="list" style="max-height:48vh;overflow:auto"></div><div class="field"><input id="chatInput" placeholder="Nhập tin nhắn"></div><button class="btn primary" id="sendChat">Gửi</button><div class="notice">Khi kết thúc hoặc rời phòng, bạn sẽ trở về đúng không gian lớp học.</div></aside></section>`);bindNav();
  const peerId=crypto.randomUUID(),wsProto=location.protocol==='https:'?'wss':'ws';
  const ws=new WebSocket(`${wsProto}://${location.host}/api/live/${classId}/ws?token=${encodeURIComponent(access.token)}`);
  const localStream=new MediaStream();let micTrack=null,camTrack=null,screenTrack=null;const peers=new Map();
  const localVideo=$('#localVideo'),placeholder=$('#localPlaceholder'); localVideo.srcObject=localStream;
  const updateUI=()=>{const camOn=!!camTrack&&camTrack.readyState==='live'&&camTrack.enabled;const micOn=!!micTrack&&micTrack.readyState==='live'&&micTrack.enabled;$('#toggleMic').textContent=micOn?'Tắt micro':'Bật micro';$('#toggleCam').textContent=camOn?'Tắt camera':'Bật camera';placeholder.classList.toggle('hidden',camOn||!!screenTrack);$('#mediaStatus').textContent=`Micro: ${micOn?'đang bật':'đang tắt'} · Camera: ${camOn?'đang bật':'đang tắt'}${screenTrack?' · Đang trình chiếu':''}`};
  async function renegotiate(id,pc){if(ws.readyState!==WebSocket.OPEN)return;const offer=await pc.createOffer();await pc.setLocalDescription(offer);ws.send(JSON.stringify({type:'offer',to:id,sdp:offer}))}
  async function syncPeer(id,pc){for(const kind of ['audio','video']){const desired=kind==='audio'?micTrack:(screenTrack||camTrack);const sender=pc.getSenders().find(x=>x.track?.kind===kind||(!x.track&&x._sfnKind===kind));if(sender){sender._sfnKind=kind;await sender.replaceTrack(desired||null)}else if(desired){const s=pc.addTrack(desired,localStream);s._sfnKind=kind}}await renegotiate(id,pc)}
  async function ensurePeer(id,initiator=false){if(peers.has(id))return peers.get(id);const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});peers.set(id,pc);if(micTrack)pc.addTrack(micTrack,localStream);if(screenTrack||camTrack)pc.addTrack(screenTrack||camTrack,localStream);pc.onicecandidate=e=>{if(e.candidate&&ws.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'ice',to:id,candidate:e.candidate}))};pc.ontrack=e=>{let v=$(`#peer_${CSS.escape(id)}`);if(!v){const tile=document.createElement('div');tile.className='video-tile';tile.innerHTML=`<video id="peer_${id}" autoplay playsinline></video><div class="video-label">Thành viên lớp</div>`;$('#stage').appendChild(tile);v=$(`#peer_${CSS.escape(id)}`)}v.srcObject=e.streams[0]};if(initiator)await renegotiate(id,pc);return pc}
  ws.onmessage=async ev=>{const m=JSON.parse(ev.data);if(m.type==='welcome'){for(const p of m.roster)if(p.id!==m.peerId)await ensurePeer(p.id,true)}if(m.type==='peer-joined')await ensurePeer(m.peer.id,true);if(m.type==='peer-left'){peers.get(m.peerId)?.close();peers.delete(m.peerId);$(`#peer_${CSS.escape(m.peerId)}`)?.parentElement?.remove()}if(m.type==='offer'){const pc=await ensurePeer(m.from);await pc.setRemoteDescription(m.sdp);const ans=await pc.createAnswer();await pc.setLocalDescription(ans);ws.send(JSON.stringify({type:'answer',to:m.from,sdp:ans}))}if(m.type==='answer'){await (await ensurePeer(m.from)).setRemoteDescription(m.sdp)}if(m.type==='ice'){try{await (await ensurePeer(m.from)).addIceCandidate(m.candidate)}catch{}}if(m.type==='chat'){$('#chat').insertAdjacentHTML('beforeend',`<div class="item"><b>${esc(m.fromName||'Thành viên')}</b><div>${esc(m.text)}</div></div>`)}};
  $('#toggleMic').onclick=async()=>{try{if(!micTrack||micTrack.readyState!=='live'){micTrack=(await navigator.mediaDevices.getUserMedia({audio:true,video:false})).getAudioTracks()[0];localStream.addTrack(micTrack)}else micTrack.enabled=!micTrack.enabled;for(const [id,pc] of peers)await syncPeer(id,pc);updateUI()}catch(e){alert('Không thể truy cập micro: '+e.message)}};
  $('#toggleCam').onclick=async()=>{try{if(!camTrack||camTrack.readyState!=='live'){camTrack=(await navigator.mediaDevices.getUserMedia({video:true,audio:false})).getVideoTracks()[0];localStream.addTrack(camTrack)}else camTrack.enabled=!camTrack.enabled;for(const [id,pc] of peers)await syncPeer(id,pc);updateUI()}catch(e){alert('Không thể truy cập camera: '+e.message)}};
  $('#shareScreen').onclick=async()=>{try{const s=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});screenTrack=s.getVideoTracks()[0];const preview=new MediaStream([screenTrack]);localVideo.srcObject=preview;for(const [id,pc] of peers)await syncPeer(id,pc);screenTrack.onended=async()=>{screenTrack=null;localVideo.srcObject=localStream;for(const [id,pc] of peers)await syncPeer(id,pc);updateUI()};updateUI()}catch(e){if(e.name!=='NotAllowedError')alert('Không thể trình chiếu: '+e.message)}};
  $('#sendChat').onclick=()=>{const text=$('#chatInput').value.trim();if(text&&ws.readyState===WebSocket.OPEN){ws.send(JSON.stringify({type:'chat',text}));$('#chat').insertAdjacentHTML('beforeend',`<div class="item"><b>Bạn</b><div>${esc(text)}</div></div>`);$('#chatInput').value=''}};
  $('#chatInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('#sendChat').click()});
  ws.onerror=()=>{$('#mediaStatus').textContent='Kết nối phòng học gặp sự cố. Hãy kiểm tra mạng và thử lại.'};
  ws.onclose=e=>{if(e.code!==1000&&location.hash===`#live/${classId}`)$('#mediaStatus').textContent='Kết nối phòng học đã ngắt. Bạn có thể rời phòng và vào lại.'};
  const cleanupLive=()=>{try{ws.close(1000,'leave')}catch{};[micTrack,camTrack,screenTrack].filter(Boolean).forEach(t=>{try{t.stop()}catch{}});peers.forEach(pc=>{try{pc.close()}catch{}});peers.clear()};state.liveCleanup=cleanupLive;
  $('#leaveRoom').onclick=()=>{cleanupLive();state.liveCleanup=null;location.hash=leaveTarget};
  updateUI();
}

async function support(){const j=await api('/api/support/tickets');app.innerHTML=shell(`<section class="hero"><div class="eyebrow">TRUNG TÂM HỖ TRỢ</div><h1>Chúng tôi ở đây khi bạn cần hỗ trợ.</h1><p>Gửi yêu cầu về tài khoản, lớp học, kiểm tra, học liệu hoặc vấn đề kỹ thuật. Mỗi yêu cầu được cấp mã ticket để bạn theo dõi quá trình xử lý. Email hỗ trợ: <b>support@skyfirst.io.vn</b>.</p></section><section class="grid"><div class="card wide"><h3>Tạo yêu cầu</h3><form id="ticketForm"><div class="field"><label>Chủ đề</label><input name="subject" required></div><div class="field"><label>Nhóm vấn đề</label><select name="category"><option>Tài khoản</option><option>Lớp học</option><option>Mic/Camera</option><option>Kiểm tra</option><option>Học liệu</option><option>Khác</option></select></div><div class="field"><label>Nội dung</label><textarea name="message" required></textarea></div><button class="btn primary">Gửi hỗ trợ</button></form></div><div class="card"><h3>Ticket của tôi</h3><div class="list">${j.tickets.map(t=>`<div class="item"><b>${esc(t.ticket_code)}</b><div>${esc(t.subject)}</div><span class="pill">${esc(t.status)}</span></div>`).join('')||'<div class="muted">Chưa có ticket.</div>'}</div></div></section>`);bindNav();$('#ticketForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r=await api('/api/support/tickets',{method:'POST',body:JSON.stringify(d)});alert(`Đã tạo ${r.ticket_code}`);location.reload()}}

async function admin(){
  if(state.user?.role==='super_admin') await api('/api/admin/system/upgrade',{method:'POST',body:'{}'}).catch(()=>{});
  const [st,reqs,users,classes,tickets,settings,anns,emails,policies,templates,activity]=await Promise.all([
    api('/api/admin/stats'),api('/api/admin/account-requests').catch(()=>({requests:[]})),api('/api/admin/users'),api('/api/admin/classes').catch(()=>({classes:[]})),api('/api/admin/tickets').catch(()=>({tickets:[]})),api('/api/admin/settings').catch(()=>({settings:{}})),api('/api/admin/announcements').catch(()=>({announcements:[]})),api('/api/admin/email-logs').catch(()=>({logs:[]})),api('/api/admin/policies').catch(()=>({policies:[]})),api('/api/admin/email-templates').catch(()=>({templates:[]})),api('/api/admin/activity').catch(()=>({activity:[]}))
  ]);
  const diagnostics=state.user?.role==='super_admin'?await api('/api/admin/system/diagnostics').catch(()=>({status:'attention',checks:[]})):{status:'restricted',checks:[]};
  const S=settings.settings||{};
  const roleOptions=(r)=>['student','assistant','teacher','account_admin','school_admin','super_admin'].map(x=>`<option value="${x}" ${r===x?'selected':''}>${x}</option>`).join('');
  app.innerHTML=shell(`<section class="hero"><div class="eyebrow">SKY FIRST CONTROL CENTER</div><h1>Trung tâm điều hành toàn hệ thống</h1><p>Điều hành tài khoản, xét duyệt hồ sơ, lớp học, nội dung công khai, email, chính sách, hỗ trợ và vận hành hệ thống trực tiếp trên website. Các tác vụ thường ngày được đưa vào giao diện quản trị để hạn chế tối đa việc phải chạy lệnh hoặc chỉnh mã nguồn.</p><div class="toolbar"><span class="pill">${st.users} tài khoản</span><span class="pill">${st.classes} lớp hoạt động</span><span class="pill">${st.pending_requests} hồ sơ chờ xử lý</span><span class="pill">${st.open_tickets} ticket đang mở</span></div></section>
  <section class="grid"><div class="card"><div class="muted">Tài khoản</div><div class="metric">${st.users}</div></div><div class="card"><div class="muted">Lớp hoạt động</div><div class="metric">${st.classes}</div></div><div class="card"><div class="muted">Yêu cầu chờ xử lý</div><div class="metric">${st.pending_requests}</div></div><div class="card"><div class="muted">Email lỗi</div><div class="metric">${st.failed_emails||0}</div></div></section>
  <section class="admin-tabs toolbar"><button class="btn primary" data-admin-tab="requests">Hồ sơ</button><button class="btn" data-admin-tab="users">Tài khoản</button><button class="btn" data-admin-tab="classes">Lớp học</button><button class="btn" data-admin-tab="tickets">Hỗ trợ</button><button class="btn" data-admin-tab="content">Website</button><button class="btn" data-admin-tab="mail">Email & chính sách</button><button class="btn" data-admin-tab="data">Dữ liệu</button><button class="btn" data-admin-tab="system">Hệ thống</button></section>

  <section id="adm-requests" class="card full admin-pane"><h2>Xét duyệt yêu cầu cấp tài khoản</h2><p class="muted">Có thể đánh dấu đang xem xét, yêu cầu bổ sung, từ chối hoặc duyệt và cấp tài khoản. Mỗi cập nhật trạng thái sẽ được ghi nhận; các trạng thái cần thiết được gửi email tự động cho người đăng ký.</p><div class="list">${reqs.requests.map(x=>`<div class="item"><div class="toolbar" style="justify-content:space-between"><div><b>${esc(x.full_name)}</b> · ${esc(x.email)}<div class="muted">${esc(x.request_code)} · ${esc(x.status)} · ${esc(x.created_at)}</div></div><span class="pill">${esc(x.status)}</span></div><div class="toolbar" style="margin-top:10px">${['pending','reviewing','needs_info'].includes(x.status)?`<button class="btn primary" data-approve="${x.id}">Duyệt & cấp SFN ID</button><button class="btn" data-review="${x.id}" data-action="reviewing">Đang xem xét</button><button class="btn" data-review="${x.id}" data-action="needs_info">Yêu cầu bổ sung</button><button class="btn" data-review="${x.id}" data-action="rejected">Từ chối</button>`:''}</div></div>`).join('')||'<div class="muted">Không có yêu cầu.</div>'}</div></section>

  <section id="adm-users" class="card full admin-pane hidden"><h2>Quản lý tài khoản SFN</h2><div class="story-grid"><form class="item" id="createUserForm"><h3>Tạo một tài khoản</h3><div class="field"><input name="full_name" placeholder="Họ và tên" required></div><div class="two"><div class="field"><input name="email" type="email" placeholder="Email" required></div><div class="field"><input name="phone" placeholder="Số điện thoại"></div></div><div class="field"><select name="role"><option value="student">Học viên</option><option value="assistant">Trợ giảng</option><option value="teacher">Giáo viên</option><option value="account_admin">Quản trị tài khoản</option><option value="school_admin">Quản trị trường học</option></select></div><button class="btn primary">Tạo & gửi kích hoạt</button></form><form class="item" id="bulkUserForm"><h3>Tạo hàng loạt</h3><p class="muted">Mỗi dòng: Họ tên,Email,SĐT,Vai trò. Tối đa 200 tài khoản/lần.</p><textarea name="csv" placeholder="Nguyễn Văn A,a@example.com,090...,student"></textarea><button class="btn">Tạo hàng loạt</button></form></div><hr><div class="list">${users.users.map(u=>`<div class="item"><b>${esc(u.sfn_id)} · ${esc(u.full_name)}</b><div class="muted">${esc(u.email)} · ${esc(u.role)} · ${esc(u.status)}</div><div class="toolbar" style="margin-top:8px">${state.user.role==='super_admin'?`<select data-role-for="${u.id}">${roleOptions(u.role)}</select><select data-status-for="${u.id}"><option value="active" ${u.status==='active'?'selected':''}>active</option><option value="disabled" ${u.status==='disabled'?'selected':''}>disabled</option><option value="pending_activation" ${u.status==='pending_activation'?'selected':''}>pending_activation</option></select><button class="btn" data-save-user="${u.id}">Lưu</button>`:''}<button class="btn" data-user-action="activation-link" data-user-id="${u.id}">Gửi link đặt mật khẩu</button><button class="btn" data-user-action="force-logout" data-user-id="${u.id}">Đăng xuất mọi phiên</button></div></div>`).join('')}</div></section>

  <section id="adm-classes" class="card full admin-pane hidden"><h2>Quản lý lớp học</h2><form id="adminCreateClass" class="item"><h3>Tạo lớp từ Control Center</h3><div class="two"><div class="field"><input name="name" placeholder="Tên lớp" required></div><div class="field"><input name="unit" placeholder="Đơn vị" value="${esc(S.default_class_unit||'Sky First Network')}"></div></div><div class="field"><input name="owner_login" placeholder="SFN ID hoặc email người phụ trách (để trống = bạn)"></div><div class="field"><textarea name="description" placeholder="Mô tả lớp"></textarea></div><button class="btn primary">Tạo lớp</button></form><div class="list">${classes.classes.map(c=>`<div class="item"><b>${esc(c.name)}</b><div class="muted">${esc(c.unit||'')} · ${c.member_count} thành viên · ${esc(c.join_code)} · ${esc(c.status)}</div><div class="toolbar" style="margin-top:8px"><button class="btn" data-class-status="${c.id}" data-value="${c.status==='active'?'archived':'active'}">${c.status==='active'?'Lưu trữ':'Mở lại'}</button><button class="btn" data-rotate-code="${c.id}">Đổi mã lớp</button><button class="btn" data-add-member="${c.id}">Thêm thành viên</button></div></div>`).join('')||'<div class="muted">Chưa có lớp.</div>'}</div></section>

  <section id="adm-tickets" class="card full admin-pane hidden"><h2>Trung tâm hỗ trợ</h2><div class="list">${tickets.tickets.map(t=>`<div class="item"><b>${esc(t.ticket_code)} · ${esc(t.subject)}</b><div class="muted">${esc(t.full_name)} · ${esc(t.email)} · ${esc(t.status)}</div><p>${esc(t.message)}</p><div class="toolbar"><select data-ticket-status="${t.id}"><option value="new" ${t.status==='new'?'selected':''}>Mới</option><option value="in_progress" ${t.status==='in_progress'?'selected':''}>Đang xử lý</option><option value="waiting_user" ${t.status==='waiting_user'?'selected':''}>Chờ người dùng</option><option value="resolved" ${t.status==='resolved'?'selected':''}>Đã giải quyết</option><option value="closed" ${t.status==='closed'?'selected':''}>Đóng</option></select><button class="btn" data-save-ticket="${t.id}">Cập nhật</button></div></div>`).join('')||'<div class="muted">Không có ticket.</div>'}</div></section>

  <section id="adm-content" class="card full admin-pane hidden"><h2>Website & nội dung công khai</h2><p class="muted">Phần này biến nội dung public thành cấu hình có thể chỉnh trực tiếp trên web, không phải sửa HTML.</p><form id="settingsForm"><div class="field"><label>Tên Trung tâm</label><input name="site_name" value="${esc(S.site_name||'Trung tâm Học tập Số Sky First Network')}"></div><div class="field"><label>Tên tiếng Anh</label><input name="site_name_en" value="${esc(S.site_name_en||'Sky First Network Digital Learning Center')}"></div><div class="field"><label>Tiêu đề mở đầu</label><input name="public_intro_title" value="${esc(S.public_intro_title||'')}"></div><div class="field"><label>Giới thiệu ngắn</label><textarea name="public_intro_text">${esc(S.public_intro_text||'')}</textarea></div><div class="field"><label>Tiêu đề phần giới thiệu</label><input name="public_about_title" value="${esc(S.public_about_title||'')}"></div><div class="field"><label>Nội dung giới thiệu mở rộng</label><textarea name="public_about_text">${esc(S.public_about_text||'')}</textarea></div><div class="two"><div class="field"><label>Email hỗ trợ</label><input name="support_email" value="${esc(S.support_email||'support@skyfirst.io.vn')}"></div><div class="field"><label>Email hệ thống</label><input name="system_email" value="${esc(S.system_email||'slc@skyfirst.io.vn')}"></div></div><div class="two"><div class="field"><label>Cổng yêu cầu tài khoản</label><select name="account_request_enabled"><option value="1" ${S.account_request_enabled!=='0'?'selected':''}>Mở</option><option value="0" ${S.account_request_enabled==='0'?'selected':''}>Tạm đóng</option></select></div><div class="field"><label>Khách vào phòng học</label><select name="allow_guest_live"><option value="1" ${S.allow_guest_live!=='0'?'selected':''}>Cho phép</option><option value="0" ${S.allow_guest_live==='0'?'selected':''}>Tắt</option></select></div></div><div class="field"><label>Dòng sản phẩm ở footer</label><input name="footer_product_text" value="${esc(S.footer_product_text||'Một sản phẩm thuộc hệ sinh thái Sky First Network.')}"></div><div class="field"><label>Bản quyền footer</label><input name="footer_copyright" value="${esc(S.footer_copyright||'© 2026 Sky First Network. Mọi quyền được bảo lưu.')}"></div>${state.user.role==='super_admin'?'<button class="btn primary">Lưu cấu hình website</button>':'<div class="notice">Chỉ Super Admin được thay đổi cấu hình.</div>'}</form><hr><h3>Thông báo công khai</h3><form id="announcementForm"><div class="two"><div class="field"><input name="title" placeholder="Tiêu đề" required></div><div class="field"><select name="status"><option value="published">Xuất bản</option><option value="draft">Bản nháp</option></select></div></div><div class="field"><textarea name="body" placeholder="Nội dung" required></textarea></div><div class="two"><div class="field"><select name="audience"><option value="public">Public</option><option value="all">Tất cả</option></select></div><div class="field"><input name="starts_at" type="datetime-local"></div></div><button class="btn">Tạo thông báo</button></form><div class="list">${anns.announcements.map(a=>`<div class="item"><b>${esc(a.title)}</b><div class="muted">${esc(a.status)} · ${esc(a.audience)}</div><div>${esc(a.body)}</div><div class="toolbar" style="margin-top:8px"><button class="btn" data-ann-toggle="${a.id}" data-status="${a.status==='published'?'draft':'published'}">${a.status==='published'?'Ẩn':'Xuất bản'}</button><button class="btn" data-ann-delete="${a.id}">Xóa</button></div></div>`).join('')}</div></section>

  <section id="adm-mail" class="card full admin-pane hidden"><h2>Email, chính sách & nội dung hệ thống</h2><h3>Mẫu email</h3><div class="list">${templates.templates.map(t=>`<form class="item template-form" data-template="${esc(t.key)}"><b>${esc(t.key)}</b><div class="field"><label>Tiêu đề email</label><input name="subject" value="${esc(t.subject)}"></div><div class="field"><label>HTML tùy chỉnh</label><textarea name="body_html" placeholder="Để trống nếu dùng template hệ thống">${esc(t.body_html||'')}</textarea></div><label><input type="checkbox" name="enabled" ${t.enabled?'checked':''}> Đang bật</label>${state.user.role==='super_admin'?'<button class="btn" style="margin-top:8px">Lưu mẫu email</button>':''}</form>`).join('')||'<div class="muted">Chưa có mẫu email.</div>'}</div><hr><h3>Chính sách</h3><div class="list">${policies.policies.map(x=>`<form class="item policy-form" data-policy="${esc(x.key)}"><b>${esc(x.key)}</b><div class="field"><input name="title" value="${esc(x.title)}"></div><div class="field"><textarea name="body_html">${esc(x.body_html)}</textarea></div>${state.user.role==='super_admin'?'<button class="btn">Lưu chính sách</button>':''}</form>`).join('')}</div></section>

  <section id="adm-data" class="card full admin-pane hidden"><h2>Dữ liệu & xuất báo cáo</h2><p class="muted">Xuất dữ liệu quản trị thành JSON ngay trên trình duyệt để lưu trữ, đối soát hoặc chuyển đổi sang Excel khi cần. Không cần truy cập D1 thủ công cho các thao tác đọc dữ liệu thường gặp.</p><div class="toolbar"><button class="btn" data-export="users">Xuất tài khoản</button><button class="btn" data-export="classes">Xuất lớp học</button><button class="btn" data-export="account_requests">Xuất yêu cầu tài khoản</button></div><hr><h3>Nhật ký quản trị</h3><div class="list">${activity.activity.slice(0,80).map(a=>`<div class="item"><b>${esc(a.action)}</b><div class="muted">${esc(a.actor_name||'Hệ thống')} · ${esc(a.created_at)}</div></div>`).join('')||'<div class="muted">Không có nhật ký hoặc bạn không có quyền xem.</div>'}</div></section>

  <section id="adm-system" class="card full admin-pane hidden"><h2>Vận hành hệ thống V10</h2><p class="muted">Bảng kiểm tra lõi giúp phát hiện nhanh thiếu binding, cấu trúc dữ liệu chưa nâng cấp hoặc cấu hình email chưa sẵn sàng.</p><div class="story-grid">${diagnostics.checks.map(x=>`<div class="item"><b>${x.ok?'✓':'!'} ${esc(x.name)}</b><div class="muted">${esc(x.detail||'')}</div></div>`).join('')||'<div class="item"><b>Chẩn đoán hệ thống</b><div class="muted">Chỉ Super Admin có quyền xem chi tiết.</div></div>'}</div><form id="systemSettings" style="margin-top:18px"><h3>Chế độ vận hành</h3><div class="two"><div class="field"><label>Bảo trì</label><select name="maintenance_mode"><option value="0" ${S.maintenance_mode!=='1'?'selected':''}>Tắt</option><option value="1" ${S.maintenance_mode==='1'?'selected':''}>Bật</option></select></div><div class="field"><label>Thời hạn phiên mặc định</label><input name="default_session_days" type="number" min="1" max="90" value="${esc(S.default_session_days||'30')}"></div></div><div class="field"><label>Thông báo bảo trì</label><textarea name="maintenance_message">${esc(S.maintenance_message||'')}</textarea></div>${state.user.role==='super_admin'?'<button class="btn primary">Lưu vận hành</button>':''}</form><div class="toolbar" style="margin-top:16px"><button class="btn" id="cleanupSessions">Dọn dữ liệu tạm hết hạn</button>${state.user.role==='super_admin'?'<button class="btn" id="runDiagnostics">Kiểm tra lõi hệ thống</button><button class="btn" id="testEmail">Gửi email kiểm tra</button>':''}</div><h3 style="margin-top:22px">Nhật ký email gần đây</h3><div class="list">${emails.logs.slice(0,40).map(e=>`<div class="item"><b>${esc(e.subject)}</b><div class="muted">${esc(e.to_email)} · ${esc(e.status)} · ${esc(e.created_at)}</div>${e.error?`<div class="notice bad">${esc(e.error).slice(0,240)}</div>`:''}</div>`).join('')||'<div class="muted">Chưa có email.</div>'}</div><div class="notice" style="margin-top:18px"><b>WEB-FIRST:</b> xét duyệt, tạo tài khoản, tạo hàng loạt, phân quyền, khóa/mở, cấp lại link mật khẩu, đăng xuất cưỡng bức, tạo/lưu trữ lớp, đổi mã lớp, thêm thành viên, xử lý ticket, nội dung website, thông báo, chính sách, mẫu email, xuất dữ liệu và dọn phiên đều được thực hiện từ Control Center.</div></section>`);
  bindNav();
  document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.admin-pane').forEach(x=>x.classList.add('hidden'));document.querySelectorAll('[data-admin-tab]').forEach(x=>x.classList.remove('primary'));b.classList.add('primary');$('#adm-'+b.dataset.adminTab).classList.remove('hidden')});
  document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{if(!confirm('Duyệt hồ sơ và cấp tài khoản SFN?'))return;const x=await api(`/api/admin/account-requests/${b.dataset.approve}/approve`,{method:'POST',body:'{}'});alert(`Đã cấp ${x.sfn_id}. Email kích hoạt: ${x.activation_email_sent?'đã gửi':'chưa gửi được'}.`);admin()});
  document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{const note=prompt(b.dataset.action==='needs_info'?'Nội dung cần người đăng ký bổ sung:':b.dataset.action==='rejected'?'Lý do/ghi chú khi từ chối:':'Ghi chú nội bộ hoặc thông tin gửi người đăng ký:')||'';await api(`/api/admin/account-requests/${b.dataset.review}/review`,{method:'POST',body:JSON.stringify({action:b.dataset.action,note})});admin()});
  document.querySelectorAll('[data-save-user]').forEach(b=>b.onclick=async()=>{const id=b.dataset.saveUser;await api(`/api/admin/users/${id}`,{method:'PATCH',body:JSON.stringify({role:$(`[data-role-for="${id}"]`).value,status:$(`[data-status-for="${id}"]`).value})});alert('Đã cập nhật tài khoản.')});
  document.querySelectorAll('[data-user-action]').forEach(b=>b.onclick=async()=>{const r=await api(`/api/admin/users/${b.dataset.userId}/${b.dataset.userAction}`,{method:'POST',body:'{}'});alert(b.dataset.userAction==='activation-link'?`Đã tạo link mới. Email: ${r.email_sent?'đã gửi':'chưa gửi được'}.`:'Đã đăng xuất các phiên của tài khoản.')});
  $('#createUserForm')?.addEventListener('submit',async e=>{e.preventDefault();const r=await api('/api/admin/users/create',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});alert(`Đã tạo ${r.sfn_id}.`);admin()});
  $('#bulkUserForm')?.addEventListener('submit',async e=>{e.preventDefault();const text=new FormData(e.target).get('csv').trim();const users=text.split(/\r?\n/).filter(Boolean).map(line=>{const [full_name,email,phone='',role='student']=line.split(',').map(x=>x.trim());return{full_name,email,phone,role}});const r=await api('/api/admin/users/bulk-create',{method:'POST',body:JSON.stringify({users})});alert(`Đã xử lý ${r.results.length} dòng; tạo mới ${r.results.filter(x=>x.status==='created').length}.`);admin()});
  document.querySelectorAll('[data-class-status]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/classes/${b.dataset.classStatus}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.value})});admin()});
  document.querySelectorAll('[data-rotate-code]').forEach(b=>b.onclick=async()=>{const r=await api(`/api/admin/classes/${b.dataset.rotateCode}/rotate-code`,{method:'POST',body:'{}'});alert(`Mã lớp mới: ${r.join_code}`);admin()});
  document.querySelectorAll('[data-add-member]').forEach(b=>b.onclick=async()=>{const login=prompt('Nhập SFN ID hoặc email thành viên:');if(!login)return;const role=prompt('Vai trò trong lớp: student / assistant / teacher','student')||'student';await api(`/api/admin/classes/${b.dataset.addMember}/members`,{method:'POST',body:JSON.stringify({login,role})});alert('Đã thêm/cập nhật thành viên.')});
  $('#adminCreateClass')?.addEventListener('submit',async e=>{e.preventDefault();const r=await api('/api/admin/classes/create',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});alert(`Đã tạo lớp. Mã: ${r.join_code}`);admin()});
  document.querySelectorAll('[data-save-ticket]').forEach(b=>b.onclick=async()=>{const id=b.dataset.saveTicket;await api(`/api/admin/tickets/${id}`,{method:'PATCH',body:JSON.stringify({status:$(`[data-ticket-status="${id}"]`).value})});alert('Đã cập nhật ticket.')});
  const saveSettings=async form=>{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});alert('Đã lưu cấu hình.')};
  $('#settingsForm')?.addEventListener('submit',async e=>{e.preventDefault();await saveSettings(e.target);await loadPublicConfig()});
  $('#systemSettings')?.addEventListener('submit',async e=>{e.preventDefault();await saveSettings(e.target)});
  $('#announcementForm')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.starts_at)delete d.starts_at;await api('/api/admin/announcements',{method:'POST',body:JSON.stringify(d)});admin()});
  document.querySelectorAll('[data-ann-toggle]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/announcements/${b.dataset.annToggle}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});admin()});
  document.querySelectorAll('[data-ann-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa thông báo này?'))return;await api(`/api/admin/announcements/${b.dataset.annDelete}`,{method:'DELETE'});admin()});
  document.querySelectorAll('.template-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));d.enabled=f.elements.enabled.checked;await api(`/api/admin/email-templates/${f.dataset.template}`,{method:'PUT',body:JSON.stringify(d)});alert('Đã lưu mẫu email.')});
  document.querySelectorAll('.policy-form').forEach(f=>f.onsubmit=async e=>{e.preventDefault();await api(`/api/admin/policies/${f.dataset.policy}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(f)))});alert('Đã lưu chính sách.')});
  document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{const r=await api(`/api/admin/export?type=${encodeURIComponent(b.dataset.export)}`);downloadJson(`skyfirst-${b.dataset.export}-${new Date().toISOString().slice(0,10)}.json`,r)});
  $('#cleanupSessions')?.addEventListener('click',async()=>{const r=await api('/api/admin/system/cleanup',{method:'POST',body:'{}'});alert(`Đã dọn: ${r.sessions||0} phiên, ${r.activation_tokens||0} token kích hoạt, ${r.live_tokens||0} token phòng học.`)});
  $('#runDiagnostics')?.addEventListener('click',async()=>{const r=await api('/api/admin/system/diagnostics');alert(r.status==='healthy'?'Các lõi chính đang sẵn sàng.':`Có ${r.failed} mục cần kiểm tra.`);admin()});
  $('#testEmail')?.addEventListener('click',async()=>{const r=await api('/api/admin/system/test-email',{method:'POST',body:'{}'});alert(r.sent?'Email kiểm tra đã được gửi.':'Chưa gửi được email: '+(r.reason||'Kiểm tra cấu hình Resend.'))});
}

async function account(){
  const sessions=await api('/api/account/sessions').catch(()=>({sessions:[]}));
  app.innerHTML=shell(`<section class="hero"><div class="eyebrow">TÀI KHOẢN SFN</div><h1>${esc(state.user.full_name)}</h1><p>${esc(state.user.sfn_id)} · ${esc(state.user.email)} · ${esc(state.user.role)}</p></section><section class="grid"><form class="card" id="profileForm"><h2>Thông tin cá nhân</h2><div class="field"><label>Họ và tên</label><input name="full_name" value="${esc(state.user.full_name)}" required></div><div class="field"><label>Số điện thoại</label><input name="phone" value="${esc(state.user.phone||'')}"></div><button class="btn primary">Lưu thay đổi</button></form><form class="card" id="passwordForm"><h2>Đổi mật khẩu</h2><div class="field"><label>Mật khẩu hiện tại</label><input type="password" name="current_password" required></div><div class="field"><label>Mật khẩu mới</label><input type="password" name="new_password" minlength="10" required></div><button class="btn">Đổi mật khẩu</button></form><div class="card full"><h2>Phiên đăng nhập</h2><p class="muted">Bạn có thể kết thúc những phiên không còn sử dụng. Phiên hiện tại được đánh dấu riêng.</p><div class="list">${sessions.sessions.map(x=>`<div class="item"><b>${x.current?'Phiên hiện tại':'Phiên đăng nhập'}</b><div class="muted">${esc(x.user_agent||'Thiết bị không xác định')} · ${esc(x.created_at)}</div>${!x.current?`<button class="btn" data-kill-session="${x.id}" style="margin-top:8px">Đăng xuất phiên này</button>`:''}</div>`).join('')}</div></div></section>`);bindNav();$('#profileForm').onsubmit=async e=>{e.preventDefault();await api('/api/account/profile',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});alert('Đã cập nhật thông tin.');await loadMe();account()};$('#passwordForm').onsubmit=async e=>{e.preventDefault();await api('/api/account/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});alert('Đã đổi mật khẩu. Các phiên khác đã được đăng xuất.');e.target.reset()};document.querySelectorAll('[data-kill-session]').forEach(b=>b.onclick=async()=>{await api(`/api/account/sessions/${b.dataset.killSession}`,{method:'DELETE'});account()})}

async function policy(type){
  const titles={privacy:'Chính sách quyền riêng tư',security:'Chính sách bảo mật',terms:'Điều khoản sử dụng'};
  let p=null;try{p=(await api(`/api/public/policies/${type}`)).policy}catch{}
  const fallback={privacy:'<p>Trung tâm Học tập Số Sky First Network xử lý thông tin cần thiết để vận hành tài khoản, lớp học và hỗ trợ. Dữ liệu xác minh và nội dung riêng tư không được công khai mặc định.</p>',security:'<p>Người dùng cần bảo vệ mật khẩu, mã kích hoạt và phiên đăng nhập. Những khu vực quản trị và dữ liệu nhạy cảm được giới hạn theo quyền truy cập.</p>',terms:'<p>Người dùng sử dụng nền tảng cho mục đích học tập và hoạt động được cho phép; không can thiệp trái phép vào hệ thống hoặc xâm phạm quyền riêng tư của người khác.</p>'}[type];
  app.innerHTML=shell(`<section class="hero"><div class="eyebrow">SKY FIRST NETWORK DIGITAL LEARNING CENTER</div><h1>${esc(p?.title||titles[type])}</h1><p>Thông tin dành cho người sử dụng Trung tâm Học tập Số Sky First Network.</p></section><div class="card full policy-card"><div>${safeRichHtml(p?.body_html||fallback)}</div><p>Nếu cần hỗ trợ về tài khoản hoặc dữ liệu, vui lòng liên hệ <b>${esc(state.site.support_email||'support@skyfirst.io.vn')}</b>.</p></div>`);bindNav()
}

async function activate(token){app.innerHTML=shell(`<div class="auth-wrap"><form class="auth-card" id="actForm"><div class="eyebrow">Kích hoạt SFN Account</div><h1>Tạo mật khẩu</h1><div class="field"><label>Mật khẩu mới</label><input name="password" type="password" minlength="10" required></div><div id="msg"></div><button class="btn primary">Kích hoạt</button></form></div>`);bindNav();$('#actForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/activate',{method:'POST',body:JSON.stringify({token,password:new FormData(e.target).get('password')})});$('#msg').innerHTML='<div class="notice good">Kích hoạt thành công. Bạn có thể đăng nhập.</div>'}catch(x){$('#msg').innerHTML=`<div class="notice bad">${esc(x.message)}</div>`}}}


async function loadSystemStatus(){try{const j=await api('/api/setup/status');state.system={initialized:!!j.initialized,schema_ready:j.schema_ready!==false}}catch{state.system={initialized:false,schema_ready:false}}}
async function loadPublicConfig(){try{const j=await api('/api/public/site-config');state.site=j.settings||{};state.siteAnnouncements=j.announcements||[];}catch{state.site={}}}
async function loadMe(){try{const j=await api('/api/auth/me');state.user=j.user;state.activeExam=j.active_exam||null}catch{state.user=null;state.activeExam=null}}
async function render(){const h=location.hash.replace(/^#/,'')||'home';if(state.site?.maintenance_mode==='1'&&!state.user&&!['login','privacy','security','terms'].includes(h)){app.innerHTML=shell(`<section class="hero"><div class="eyebrow">THÔNG BÁO HỆ THỐNG</div><h1>Trung tâm đang được bảo trì.</h1><p>${esc(state.site.maintenance_message||'Vui lòng quay lại sau.')}</p><button class="btn" data-go="login">Đăng nhập quản trị</button></section>`);bindNav();return;}if(!state.system.initialized && !['privacy','security','terms'].includes(h) && !h.startsWith('activate/')) return setupFirstAdmin();if(!state.user && !['home','login','request','lookup','privacy','security','terms'].includes(h) && !h.startsWith('activate/') && !h.startsWith('guest-live/')) await loadMe();if(state.user&&state.activeExam&&!h.startsWith('exam/')&&!['login'].includes(h)){location.hash=`exam/${state.activeExam.attempt_id}`;return;}if(h==='home')return state.user?home():landing();if(h==='login')return login();if(h==='request')return requestAccount();if(h==='lookup')return lookupAccount();if(h==='classes')return state.user?classes():login();if(h==='support')return state.user?support():login();if(h==='account')return state.user?account():login();if(h==='admin')return state.user?admin():login();if(h==='privacy'||h==='security'||h==='terms')return policy(h);if(h.startsWith('class/'))return state.user?classView(h.split('/')[1]):login();if(h.startsWith('live/'))return state.user?liveRoom(h.split('/')[1]):login();if(h.startsWith('guest-live/'))return guestLiveEntry(h.split('/')[1]);if(h.startsWith('activate/'))return activate(h.split('/')[1]);if(h.startsWith('exam/'))return state.user?resumeExam(h.split('/')[1]):login();if(h.startsWith('join/')){if(!state.user)return login();const code=decodeURIComponent(h.split('/')[1]);try{const r=await api('/api/classes/join',{method:'POST',body:JSON.stringify({code})});location.hash=`class/${r.class_id}`}catch(e){alert(e.message)}return}landing()}
window.addEventListener('hashchange',render);await loadSystemStatus();await loadPublicConfig();await loadMe();render();
